import { create } from 'zustand'
import {
  classifyPreCuePress,
  classifyRep,
  pickNextCue,
  pickPreCueDelayMs,
  summarize,
  type ClassifyOutput,
} from '../engine/drill'
import { defaultRng, type RNG } from '../engine/rng'
import {
  DEFAULT_DRILL_CONFIG,
  type CueDef,
  type DrillConfig,
  type RepRecord,
  type SessionRecord,
} from '../engine/types'
import { saveRep, saveSession } from './db'

export type DrillPhase =
  | 'idle'
  | 'waiting'
  | 'showing'
  | 'feedback'
  | 'ended'

interface RepInFlight {
  cue: CueDef
  preCueStartedAt: number
  preCueDelayMs: number
  cueShownAt: number | null
}

export interface FeedbackState {
  rep: RepRecord
  cue: CueDef
}

interface SessionState {
  phase: DrillPhase
  sessionId: string | null
  sessionStartedAt: number | null
  config: DrillConfig
  current: RepInFlight | null
  feedback: FeedbackState | null
  reps: RepRecord[]
  persistError: string | null
  rng: RNG

  start: (overrides?: Partial<DrillConfig>, rng?: RNG) => void
  beginRep: () => void
  revealCue: () => void
  recordPress: (at: number) => void
  finishWindow: () => void
  acknowledgeFeedback: () => void
  stop: () => void
  reset: () => void
}

function newId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `id-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export const useSession = create<SessionState>((set, get) => {
  function persistSession(
    sessionId: string,
    startedAt: number,
    endedAt: number | null,
    reps: RepRecord[],
  ): void {
    const record: SessionRecord = {
      id: sessionId,
      startedAt,
      endedAt,
      drillType: 'first_beat_go_no_go',
      repCount: reps.length,
      summary: summarize(reps),
    }
    void saveSession(record).catch((err) => {
      set({ persistError: (err as Error).message })
    })
  }

  function commitRep(
    cue: CueDef,
    cueShownAt: number,
    pressedAt: number | null,
    classification: ClassifyOutput,
  ): void {
    const state = get()
    if (!state.sessionId || state.sessionStartedAt === null) return
    const rep: RepRecord = {
      id: newId(),
      sessionId: state.sessionId,
      cueId: cue.id,
      isGo: cue.isGo,
      result: classification.result,
      reactionMs: classification.reactionMs,
      score: classification.score,
      cueShownAt,
      pressedAt,
    }
    void saveRep(rep)
    const nextReps = [...state.reps, rep]
    set({
      phase: 'feedback',
      feedback: { rep, cue },
      reps: nextReps,
    })
    persistSession(state.sessionId, state.sessionStartedAt, null, nextReps)
  }

  return {
    phase: 'idle',
    sessionId: null,
    sessionStartedAt: null,
    config: DEFAULT_DRILL_CONFIG,
    current: null,
    feedback: null,
    reps: [],
    persistError: null,
    rng: defaultRng,

    start: (overrides, rng) => {
      const config = { ...DEFAULT_DRILL_CONFIG, ...overrides }
      const sessionId = newId()
      const startedAt = Date.now()
      set({
        phase: 'waiting',
        sessionId,
        sessionStartedAt: startedAt,
        config,
        current: null,
        feedback: null,
        reps: [],
        persistError: null,
        rng: rng ?? defaultRng,
      })
      persistSession(sessionId, startedAt, null, [])
      get().beginRep()
    },

    beginRep: () => {
      const { config, phase, rng } = get()
      if (phase === 'idle' || phase === 'ended') return
      const cue = pickNextCue(rng, config)
      const preCueDelayMs = pickPreCueDelayMs(rng, config)
      set({
        phase: 'waiting',
        feedback: null,
        current: {
          cue,
          preCueStartedAt: performance.now(),
          preCueDelayMs,
          cueShownAt: null,
        },
      })
    },

    revealCue: () => {
      const { current } = get()
      if (!current) return
      set({
        phase: 'showing',
        current: { ...current, cueShownAt: performance.now() },
      })
    },

    recordPress: (at) => {
      const { phase, current, config } = get()
      if (!current) return

      if (phase === 'waiting') {
        commitRep(current.cue, at, at, classifyPreCuePress())
        return
      }
      if (phase !== 'showing' || current.cueShownAt === null) return

      const classification = classifyRep({
        cue: current.cue,
        cueShownAt: current.cueShownAt,
        pressedAt: at,
        responseWindowMs: config.responseWindowMs,
        hesitationThresholdMs: config.hesitationThresholdMs,
      })
      commitRep(current.cue, current.cueShownAt, at, classification)
    },

    finishWindow: () => {
      const { phase, current, config } = get()
      if (phase !== 'showing' || !current || current.cueShownAt === null) return
      const classification = classifyRep({
        cue: current.cue,
        cueShownAt: current.cueShownAt,
        pressedAt: null,
        responseWindowMs: config.responseWindowMs,
        hesitationThresholdMs: config.hesitationThresholdMs,
      })
      commitRep(current.cue, current.cueShownAt, null, classification)
    },

    acknowledgeFeedback: () => {
      const { config, reps } = get()
      if (config.maxReps !== null && reps.length >= config.maxReps) {
        get().stop()
        return
      }
      get().beginRep()
    },

    stop: () => {
      const { sessionId, sessionStartedAt, reps } = get()
      if (sessionId && sessionStartedAt !== null) {
        persistSession(sessionId, sessionStartedAt, Date.now(), reps)
      }
      set({ phase: 'ended', current: null })
    },

    reset: () => {
      set({
        phase: 'idle',
        sessionId: null,
        sessionStartedAt: null,
        current: null,
        feedback: null,
        reps: [],
        persistError: null,
      })
    },
  }
})

export function getSessionSummary(reps: RepRecord[]) {
  return summarize(reps)
}

import { GO_CUES, NO_GO_CUES } from '../cues/library'
import type {
  CueDef,
  DrillConfig,
  RepRecord,
  RepResult,
  SessionSummary,
} from './types'
import { SCORE_TABLE } from './types'
import { randInt, type RNG } from './rng'

export function pickPreCueDelayMs(rng: RNG, config: DrillConfig): number {
  return randInt(rng, config.preCueMinMs, config.preCueMaxMs)
}

export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
  const isGo = rng() < config.goCueProbability
  const pool = isGo ? GO_CUES : NO_GO_CUES
  if (pool.length === 0) {
    throw new Error('pickNextCue: empty pool')
  }
  return pool[Math.floor(rng() * pool.length)]
}

export interface ClassifyInput {
  cue: CueDef
  cueShownAt: number
  pressedAt: number | null
  responseWindowMs: number
  hesitationThresholdMs: number
}

export interface ClassifyOutput {
  result: RepResult
  reactionMs: number | null
  score: number
}

export function classifyRep(input: ClassifyInput): ClassifyOutput {
  const { cue, cueShownAt, pressedAt, responseWindowMs, hesitationThresholdMs } =
    input

  if (pressedAt !== null && pressedAt < cueShownAt) {
    return wrap('false_start', null)
  }

  const pressedInWindow =
    pressedAt !== null && pressedAt - cueShownAt <= responseWindowMs

  if (!pressedInWindow) {
    return wrap(cue.isGo ? 'late' : 'correct_no_go', null)
  }

  const dt = (pressedAt as number) - cueShownAt
  if (!cue.isGo) {
    return wrap('false_start', dt)
  }

  return wrap(dt < hesitationThresholdMs ? 'correct_go' : 'hesitation', dt)
}

export function classifyPreCuePress(): ClassifyOutput {
  return wrap('false_start', null)
}

function wrap(result: RepResult, reactionMs: number | null): ClassifyOutput {
  return { result, reactionMs, score: SCORE_TABLE[result] }
}

export function summarize(reps: RepRecord[]): SessionSummary {
  const reactionTimes = reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)

  const avgReactionMs =
    reactionTimes.length === 0
      ? null
      : Math.round(
          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
        )

  return {
    reps: reps.length,
    correct: reps.filter(
      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
    ).length,
    falseStarts: reps.filter((r) => r.result === 'false_start').length,
    lateMisses: reps.filter((r) => r.result === 'late').length,
    hesitations: reps.filter((r) => r.result === 'hesitation').length,
    score: reps.reduce((a, r) => a + r.score, 0),
    avgReactionMs,
  }
}

import { useEffect } from 'react'
import { useSession } from '../store/session'
import type { RepResult } from '../engine/types'

const FEEDBACK_HOLD_MS = 1000

export function TrainerScreen() {
  const phase = useSession((s) => s.phase)
  const current = useSession((s) => s.current)
  const feedback = useSession((s) => s.feedback)
  const config = useSession((s) => s.config)
  const reps = useSession((s) => s.reps)
  const revealCue = useSession((s) => s.revealCue)
  const recordPress = useSession((s) => s.recordPress)
  const finishWindow = useSession((s) => s.finishWindow)
  const acknowledgeFeedback = useSession((s) => s.acknowledgeFeedback)
  const stop = useSession((s) => s.stop)

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.repeat) return
      if (e.code === 'Space') {
        e.preventDefault()
        if (phase === 'waiting' || phase === 'showing') {
          recordPress(performance.now())
        } else if (phase === 'feedback') {
          acknowledgeFeedback()
        }
      } else if (e.key === 'Escape') {
        stop()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [phase, recordPress, acknowledgeFeedback, stop])

  useEffect(() => {
    if (phase !== 'waiting' || !current || current.cueShownAt !== null) return
    const timer = window.setTimeout(revealCue, current.preCueDelayMs)
    return () => window.clearTimeout(timer)
  }, [phase, current, revealCue])

  useEffect(() => {
    if (phase !== 'showing' || !current?.cueShownAt) return
    const timer = window.setTimeout(finishWindow, config.responseWindowMs)
    return () => window.clearTimeout(timer)
  }, [phase, current, config.responseWindowMs, finishWindow])

  useEffect(() => {
    if (phase !== 'feedback') return
    const timer = window.setTimeout(acknowledgeFeedback, FEEDBACK_HOLD_MS)
    return () => window.clearTimeout(timer)
  }, [phase, acknowledgeFeedback])

  const repsDone = reps.length

  return (
    <div
      className={`screen trainer trainer-${
        phase === 'feedback' && feedback ? feedback.rep.result : phase
      }`}
    >
      <header className="hud">
        <span>Rep {repsDone + (phase === 'ended' ? 0 : 1)}</span>
        <button
          type="button"
          className="link"
          onClick={stop}
          aria-label="Stop drill"
        >
          Stop (Esc)
        </button>
      </header>

      <main className="stage">
        {phase === 'waiting' && (
          <div className="ready">
            <span className="ready-label">READY</span>
            <span className="dot" />
          </div>
        )}

        {phase === 'showing' && current && (
          <div className="cue">
            <span className="cue-label">{current.cue.label}</span>
            <span className="cue-sub">
              {current.cue.isGo ? 'Commit now' : 'Hold position'}
            </span>
          </div>
        )}

        {phase === 'feedback' && feedback && (
          <div className="feedback">
            <span className="feedback-label">
              {feedbackLabel(feedback.rep.result)}
            </span>
            {feedback.rep.reactionMs !== null && (
              <span className="feedback-sub">
                {Math.round(feedback.rep.reactionMs)} ms
              </span>
            )}
          </div>
        )}
      </main>
    </div>
  )
}

function feedbackLabel(result: RepResult): string {
  switch (result) {
    case 'correct_go':
      return 'GO ✓'
    case 'correct_no_go':
      return 'HOLD ✓'
    case 'late':
      return 'LATE'
    case 'false_start':
      return 'FALSE START'
    case 'hesitation':
      return 'HESITATION'
  }
}

import { useEffect, useState } from 'react'
import { listRecentSessions } from '../store/db'
import { useSession } from '../store/session'
import type { SessionRecord } from '../engine/types'

export function IdleScreen() {
  const start = useSession((s) => s.start)
  const [recent, setRecent] = useState<SessionRecord[]>([])

  useEffect(() => {
    void listRecentSessions(5).then(setRecent)
  }, [])

  return (
    <div className="screen idle">
      <h1>PointFight Reactor</h1>
      <p className="subtitle">First-beat go / no-go drill</p>

      <button
        className="primary"
        type="button"
        onClick={() => {
          void requestFullscreen()
          start()
        }}
        autoFocus
      >
        Start drill
      </button>
      <p className="hint">
        Press <kbd>Space</kbd> to commit. Press <kbd>Esc</kbd> to stop.
      </p>

      {recent.length > 0 && (
        <div className="recent">
          <h2>Recent sessions</h2>
          <ul>
            {recent.map((s) => (
              <li key={s.id}>
                <span className="when">
                  {new Date(s.startedAt).toLocaleString()}
                </span>
                <span className="meta">
                  {s.repCount} reps · score {s.summary.score}
                  {s.summary.avgReactionMs !== null &&
                    ` · ${s.summary.avgReactionMs}ms avg`}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

async function requestFullscreen(): Promise<void> {
  try {
    if (document.fullscreenElement) return
    await document.documentElement.requestFullscreen()
  } catch {
    /* user can run windowed; no-op */
  }
}

import { useMemo } from 'react'
import { useSession, getSessionSummary } from '../store/session'
import { CUE_LIBRARY } from '../cues/library'
import type { CueId } from '../engine/types'

export function SummaryScreen() {
  const reps = useSession((s) => s.reps)
  const reset = useSession((s) => s.reset)
  const start = useSession((s) => s.start)
  const persistError = useSession((s) => s.persistError)

  const summary = useMemo(() => getSessionSummary(reps), [reps])

  const byCue = useMemo(() => {
    const map = new Map<CueId, { reps: number; correct: number }>()
    for (const cue of CUE_LIBRARY) {
      map.set(cue.id, { reps: 0, correct: 0 })
    }
    for (const r of reps) {
      const row = map.get(r.cueId)
      if (!row) continue
      row.reps++
      if (r.result === 'correct_go' || r.result === 'correct_no_go') {
        row.correct++
      }
    }
    return map
  }, [reps])

  return (
    <div className="screen summary">
      <h1>Session summary</h1>

      {persistError && (
        <div className="banner warn">
          Storage unavailable: {persistError}. Session was kept in memory only.
        </div>
      )}

      <div className="stats">
        <Stat label="Reps" value={summary.reps} />
        <Stat label="Score" value={summary.score} />
        <Stat label="Correct" value={summary.correct} />
        <Stat label="False starts" value={summary.falseStarts} />
        <Stat label="Hesitations" value={summary.hesitations} />
        <Stat label="Late misses" value={summary.lateMisses} />
        <Stat
          label="Avg reaction"
          value={
            summary.avgReactionMs === null
              ? '—'
              : `${summary.avgReactionMs} ms`
          }
        />
      </div>

      <h2>By cue</h2>
      <table className="cue-table">
        <thead>
          <tr>
            <th>Cue</th>
            <th>Reps</th>
            <th>Correct</th>
          </tr>
        </thead>
        <tbody>
          {CUE_LIBRARY.map((cue) => {
            const row = byCue.get(cue.id) ?? { reps: 0, correct: 0 }
            return (
              <tr key={cue.id}>
                <td>
                  {cue.label}{' '}
                  <span className="tag">{cue.isGo ? 'go' : 'no-go'}</span>
                </td>
                <td>{row.reps}</td>
                <td>{row.correct}</td>
              </tr>
            )
          })}
        </tbody>
      </table>

      <div className="actions">
        <button type="button" className="primary" onClick={() => start()}>
          Start another session
        </button>
        <button type="button" className="link" onClick={() => reset()}>
          Back to start
        </button>
      </div>
    </div>
  )
}

function Stat({ label, value }: { label: string; value: number | string }) {
  return (
    <div className="stat">
      <span className="stat-value">{value}</span>
      <span className="stat-label">{label}</span>
    </div>
  )
}

