  border: 1px solid var(--gym-neutral);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 1rem;
}

kbd {
  display: inline-block;
  padding: 0.1em 0.55em;
  border-radius: 6px;
  border: 1px solid var(--gym-neutral);
  background: #111827;
  font-family: ui-monospace, monospace;
  font-size: 0.95em;
}

/* ---- Idle screen ---- */
.screen.idle {
  gap: 1.8rem;
  text-align: center;
}
.screen.idle h1 {
  margin: 0;
  font-size: clamp(2.8rem, 6vw, 4.6rem);
  letter-spacing: -1.5px;
}
.screen.idle .subtitle {
  margin: -0.6rem 0 0;
  color: var(--gym-muted);
  font-size: 1.4rem;
}
.screen.idle .hint {
  color: var(--gym-muted);
  font-size: 1.1rem;
}
.recent {
  width: min(640px, 100%);
  margin-top: 1rem;
  border-top: 1px solid var(--gym-neutral);
  padding-top: 1rem;
  text-align: left;
}
.recent h2 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--gym-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 0.6rem;
}
.recent ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.recent li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  font-size: 1rem;
  padding: 0.4rem 0.6rem;
  background: var(--gym-neutral);
  border-radius: 6px;
}
.recent .when {
  color: var(--gym-fg);
}
.recent .meta {
  color: var(--gym-muted);
}

