.screen.trainer {
  position: relative;
  padding: 0;
  transition: background-color 80ms linear;
}
.screen.trainer .hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.5rem;
  font-size: 1.1rem;
  color: var(--gym-muted);
  z-index: 2;
}
.screen.trainer .stage {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.ready,
.cue,
.feedback {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.2rem;
