1	import { GO_CUES, NO_GO_CUES } from '../cues/library'
2	import type {
3	  CueDef,
4	  DrillConfig,
5	  RepRecord,
6	  RepResult,
7	  SessionSummary,
8	} from './types'
9	import {
10	  PRE_CUE_MAX_CEILING_MS,
11	  PRE_CUE_MIN_FLOOR_MS,
12	  SCORE_TABLE,
13	} from './types'
14	import { randInt, type RNG } from './rng'
15	
16	export function pickPreCueDelayMs(rng: RNG, config: DrillConfig): number {
17	  return randInt(rng, config.preCueMinMs, config.preCueMaxMs)
18	}
19	
20	export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
21	  const isGo = rng() < config.goCueProbability
22	  const pool = isGo ? GO_CUES : NO_GO_CUES
23	  if (pool.length === 0) {
24	    throw new Error('pickNextCue: empty pool')
25	  }
26	  return pool[Math.floor(rng() * pool.length)]
27	}
28	
29	export interface ClassifyInput {
30	  cue: CueDef
31	  cueShownAt: number
32	  pressedAt: number | null
33	  responseWindowMs: number
34	  hesitationThresholdMs: number
35	}
36	
37	export interface ClassifyOutput {
38	  result: RepResult
39	  reactionMs: number | null
40	  score: number
41	}
42	
43	export function classifyRep(input: ClassifyInput): ClassifyOutput {
44	  const { cue, cueShownAt, pressedAt, responseWindowMs, hesitationThresholdMs } =
45	    input
46	
47	  if (pressedAt !== null && pressedAt < cueShownAt) {
48	    return wrap('false_start', null)
49	  }
50	
51	  const pressedInWindow =
52	    pressedAt !== null && pressedAt - cueShownAt <= responseWindowMs
53	
54	  if (!pressedInWindow) {
55	    return wrap(cue.isGo ? 'late' : 'correct_no_go', null)
56	  }
57	
58	  const dt = (pressedAt as number) - cueShownAt
59	  if (!cue.isGo) {
60	    return wrap('false_start', dt)
61	  }
62	
63	  return wrap(dt < hesitationThresholdMs ? 'correct_go' : 'hesitation', dt)
64	}
65	
66	export function classifyPreCuePress(): ClassifyOutput {
67	  return wrap('false_start', null)
68	}
69	
70	function wrap(result: RepResult, reactionMs: number | null): ClassifyOutput {
71	  return { result, reactionMs, score: SCORE_TABLE[result] }
72	}
73	
74	export interface ValidationError {
75	  field: keyof DrillConfig
76	  message: string
77	}
78	
79	export function validateDrillConfig(config: DrillConfig): ValidationError[] {
80	  const errors: ValidationError[] = []
81	  if (config.preCueMinMs < PRE_CUE_MIN_FLOOR_MS) {
82	    errors.push({
83	      field: 'preCueMinMs',
84	      message: `must be ≥ ${PRE_CUE_MIN_FLOOR_MS}ms`,
85	    })
86	  }
87	  if (config.preCueMaxMs > PRE_CUE_MAX_CEILING_MS) {
88	    errors.push({
89	      field: 'preCueMaxMs',
90	      message: `must be ≤ ${PRE_CUE_MAX_CEILING_MS}ms`,
91	    })
92	  }
93	  if (config.preCueMinMs > config.preCueMaxMs) {
94	    errors.push({
95	      field: 'preCueMaxMs',
96	      message: 'must be ≥ min',
97	    })
98	  }
99	  if (config.rounds < 1) {
100	    errors.push({ field: 'rounds', message: 'must be ≥ 1' })
101	  }
102	  if (config.workMs < 1_000) {
103	    errors.push({ field: 'workMs', message: 'must be ≥ 1s' })
104	  }
105	  if (config.restMs < 0) {
106	    errors.push({ field: 'restMs', message: 'must be ≥ 0' })
107	  }
108	  if (config.perFalseStartPenalty < 0) {
109	    errors.push({ field: 'perFalseStartPenalty', message: 'must be ≥ 0' })
110	  }
111	  if (config.perHesitationPenalty < 0) {
112	    errors.push({ field: 'perHesitationPenalty', message: 'must be ≥ 0' })
113	  }
114	  return errors
115	}
116	
117	export function pendingPenalties(
118	  reps: RepRecord[],
119	  perFalseStart: number,
120	  perHesitation: number,
121	  cleared: number,
122	): number {
123	  const earned = reps.reduce((sum, r) => {
124	    if (r.result === 'false_start') return sum + perFalseStart
125	    if (r.result === 'hesitation') return sum + perHesitation
126	    return sum
127	  }, 0)
128	  return Math.max(0, earned - cleared)
129	}
130	
131	export function summarize(reps: RepRecord[]): SessionSummary {
132	  const reactionTimes = reps
133	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
134	    .map((r) => r.reactionMs as number)
135	
136	  const avgReactionMs =
137	    reactionTimes.length === 0
138	      ? null
139	      : Math.round(
140	          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
141	        )
142	
143	  return {
144	    reps: reps.length,
145	    correct: reps.filter(
146	      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
147	    ).length,
148	    falseStarts: reps.filter((r) => r.result === 'false_start').length,
149	    lateMisses: reps.filter((r) => r.result === 'late').length,
150	    hesitations: reps.filter((r) => r.result === 'hesitation').length,
151	    score: reps.reduce((a, r) => a + r.score, 0),
152	    avgReactionMs,
153	  }
154	}
