5	export class ReactorDB extends Dexie {
6	  sessions!: EntityTable<SessionRecord, 'id'>
7	  reps!: EntityTable<RepRecord, 'id'>
8	  settings!: EntityTable<SettingsRecord, 'id'>
9	
10	  constructor() {
11	    super('pointfight-reactor')
12	    this.version(1).stores({
13	      sessions: 'id, startedAt',
14	      reps: 'id, sessionId, cueId',
15	    })
16	    this.version(2).stores({
17	      sessions: 'id, startedAt',
18	      reps: 'id, sessionId, cueId',
19	      settings: 'id',
20	    })
21	  }
22	}
23	
24	let _db: ReactorDB | null = null
25	let _openError: Error | null = null
26	
27	export function getDb(): ReactorDB | null {
28	  if (_db) return _db
29	  if (_openError) return null
30	  try {
31	    _db = new ReactorDB()
32	    return _db
33	  } catch (err) {
34	    _openError = err instanceof Error ? err : new Error(String(err))
35	    return null
36	  }
37	}
38	
39	export function getDbError(): Error | null {
40	  return _openError
41	}
42	
43	export async function saveSession(session: SessionRecord): Promise<void> {
44	  const db = getDb()
45	  if (!db) return
46	  try {
47	    await db.sessions.put(session)
48	  } catch (err) {
49	    _openError = err instanceof Error ? err : new Error(String(err))
50	  }
51	}
52	
53	export async function saveRep(rep: RepRecord): Promise<void> {
54	  const db = getDb()
55	  if (!db) return
56	  try {
57	    await db.reps.put(rep)
58	  } catch (err) {
59	    _openError = err instanceof Error ? err : new Error(String(err))
60	  }
61	}
62	
63	export async function listRecentSessions(limit = 20): Promise<SessionRecord[]> {
64	  const db = getDb()
65	  if (!db) return []
66	  try {
67	    return await db.sessions
68	      .orderBy('startedAt')
69	      .reverse()
70	      .limit(limit)
71	      .toArray()
72	  } catch {
73	    return []
