// ---------- Criterion 5: Pre-cue delay accepts up to 8000, rejects 9000 ----------
await setNumber('^Min \\(ms\\)$', 2000)
await setNumber('^Max \\(ms\\)$', 8000)

await page.getByRole('button', { name: 'Save' }).click()
// If save succeeded we should be back on idle
try {
