// ---------- Output ----------
writeFileSync(join(OUT, 'results.json'), JSON.stringify({ results, consoleErrors }, null, 2))
console.log('\n=== Console errors ===')
console.log(consoleErrors.length ? consoleErrors.join('\n') : '(none)')
console.log('\n=== Summary ===')
